public static String salaries(int[] rates, int[][] hours) {
    String s = "";
    for (int i = 0; i < rates.length; i++) {
        int total = 0;   // סך השעות של המלצר
        for (int d = 0; d < hours[i].length; d++) {
            total = total + hours[i][d];
        }
        s = s + rates[i] * total + " ";
    }
    return s;
}

public static double averageSalary(int[] rates, int[][] hours) {
    int sum = 0;
    for (int i = 0; i < rates.length; i++) {
        for (int d = 0; d < hours[i].length; d++) {
            sum = sum + rates[i] * hours[i][d];
        }
    }
    return (double) sum / rates.length;
}

