System.out.println("סעיף א, בדיקה 2 (מלצר אחד, יום אחד): " + check(salaries(new int[] { 35 }, new int[][] { new int[] { 7 } }), "245"));
System.out.println("סעיף א, בדיקה 3 (מלצר שלא עבד): " + check(salaries(new int[] { 40, 60 }, new int[][] { new int[] { 0, 0 }, new int[] { 5, 3 } }), "0 480"));
System.out.println("סעיף ב, בדיקה 1 (הדוגמה): " + check(averageSalary(new int[] { 40, 50, 45 }, new int[][] { new int[] { 8, 6, 0, 5 }, new int[] { 4, 8, 8, 2 }, new int[] { 6, 6, 6, 6 } }), 980.0));
System.out.println("סעיף ב, בדיקה 2 (ממוצע לא שלם): " + check(averageSalary(new int[] { 30, 31 }, new int[][] { new int[] { 2, 1 }, new int[] { 1, 2 } }), 91.5));

